import com.alan.clients.value.impl.NumberValue;
import io.netty.buffer.Unpooled;
import net.minecraft.network.PacketBuffer;
import net.minecraft.network.play.client.C17PacketCustomPayload;
import org.apache.commons.lang3.RandomStringUtils;

public class ChannelConsoleSpammer extends Mode<ConsoleSpammer> {

    private final NumberValue channelsPerTick = new NumberValue("Channels/tick", this, 1, 1, 100, 1);

    public ChannelConsoleSpammer(String name, ConsoleSpammer parent) {
        super(name, parent);
    }

    @EventLink
    public final Listener<TickEvent> onTick = event -> {
        for (int i = 0; i < channelsPerTick.getValue().intValue(); ++i) {
            final PacketBuffer buffer = new PacketBuffer(Unpooled.buffer());
            buffer.writeString("MC|" + RandomStringUtils.randomAlphabetic(8, 16));

            PacketUtil.send(new C17PacketCustomPayload("REGISTER", buffer));
        }
    };
}
// NOTE (AI): ChannelConsoleSpammer is a Mode of the Rise 6.x ConsoleSpammer. Every tick it sends up to channelsPerTick REGISTER packets, each carrying a random 'MC|' + 8-16 random letters channel name. The payload is a registration for channels the client never uses; the spam is aimed at server consoles and plugin channel registries that log or allocate per REGISTER.

